import gzip,sys,urllib.request,csv,collections,math
import pysam
inp,out=sys.argv[1:3]
META="https://storage.googleapis.com/gcp-public-data--gnomad/release/3.1/secondary_analyses/hgdp_1kg/metadata_and_qc/gnomad_meta_v1.tsv"
BCF="https://storage.googleapis.com/gcp-public-data--gnomad/resources/hgdp_1kg/phased_haplotypes_v2/hgdp1kgp_chr1.filtered.SNV_INDEL.phased.shapeit5.bcf"
with open(inp,"rb") as q: isgz=q.read(2)==b"\x1f\x8b"
op=gzip.open if isgz else open
sites=[]
samples=[]
with op(inp,"rt",errors="replace") as f:
  for line in f:
    if line.startswith("#CHROM"):
      samples=line.rstrip().split("\t")[9:13]
    elif not line.startswith("#"):
      a=line.rstrip().split("\t")
      if len(a)<13 or len(a[3])!=1 or len(a[4])!=1: continue
      fmt=a[8].split(":"); gi=fmt.index("GT") if "GT" in fmt else 0
      g=[]
      for x in a[9:13]:
        z=x.split(":"); gt=z[gi] if gi<len(z) else "."
        aa=gt.replace("|","/").split("/")
        if len(aa)!=2 or "." in aa: g.append(None)
        else:
          alleles=[a[3],a[4]]
          try:g.append(tuple(sorted((alleles[int(aa[0])],alleles[int(aa[1])]))))
          except:g.append(None)
      if len(set(x for x in g if x is not None))>1: sites.append((int(a[1]),a[3],a[4],g))
N=240
sel=[sites[(i*len(sites))//N] for i in range(N)]
with urllib.request.urlopen(META) as r:
  rd=csv.DictReader((x.decode() for x in r),delimiter="\t")
  label={}
  mp={"CSA":"SAS"}
  for row in rd:
    lab=mp.get(row.get("hgdp_tgp_meta.Genetic.region",""),row.get("hgdp_tgp_meta.Genetic.region",""))
    if lab in {"AFR","EAS","SAS","EUR","MID","OCE"}: label[row["s"]]=lab
vf=pysam.VariantFile(BCF)
refs=list(vf.header.samples)
matches=[[0]*len(refs) for _ in range(4)]
comp=[[0]*len(refs) for _ in range(4)]
found=0
for pos,iref,ialt,ig in sel:
  recs=list(vf.fetch("chr1",pos-1,pos))
  rec=None
  for rr in recs:
    if rr.pos==pos and iref in rr.alleles and ialt in rr.alleles:
      rec=rr; break
  if rec is None: continue
  found+=1
  alleles=rec.alleles
  for j,s in enumerate(refs):
    gt=rec.samples[s].get("GT")
    if gt is None or len(gt)!=2 or None in gt: continue
    try: rg=tuple(sorted((alleles[gt[0]],alleles[gt[1]])))
    except: continue
    for k in range(4):
      if ig[k] is not None:
        comp[k][j]+=1
        if rg==ig[k]: matches[k][j]+=1
with open(out,"w") as w:
  w.write(f"input_samples\t{','.join(samples)}\nselected_variable_sites\t{len(sel)}\nreference_sites_found\t{found}\nreference_samples\t{len(refs)}\n")
  for k,samp in enumerate(samples):
    ranked=sorted(range(len(refs)),key=lambda j:(matches[k][j]/comp[k][j] if comp[k][j] else -1,matches[k][j]),reverse=True)[:15]
    w.write("sample\t"+samp+"\n")
    for j in ranked:
      lab=label.get(refs[j],"NA"); w.write(f"hit\t{refs[j]}\t{lab}\t{matches[k][j]}/{comp[k][j]}\t{matches[k][j]/comp[k][j]:.6f}\n")
    by=collections.defaultdict(list)
    for j,rn in enumerate(refs):
      if rn in label and comp[k][j]: by[label[rn]].append(matches[k][j]/comp[k][j])
    for lab,vals in sorted(by.items()):
      vals.sort(reverse=True); top=vals[:max(5,len(vals)//20)]
      w.write(f"label\t{lab}\tmax={vals[0]:.6f}\ttop5pct_mean={sum(top)/len(top):.6f}\tn={len(vals)}\n")

