import gzip,sys,urllib.request,csv
import pysam
from pyliftover import LiftOver
inp,out=sys.argv[1:3]
ids=["LP6005442-DNA_B02","LP6005441-DNA_F01","HG02724","HG00190"]
META="https://storage.googleapis.com/gcp-public-data--gnomad/release/3.1/secondary_analyses/hgdp_1kg/metadata_and_qc/gnomad_meta_v1.tsv"
BCF="https://storage.googleapis.com/gcp-public-data--gnomad/resources/hgdp_1kg/phased_haplotypes_v2/hgdp1kgp_chr1.filtered.SNV_INDEL.phased.shapeit5.bcf"
urllib.request.urlretrieve("https://hgdownload.soe.ucsc.edu/goldenPath/hg19/liftOver/hg19ToHg38.over.chain.gz","chain.gz")
lo=LiftOver("chain.gz")
with open(inp,"rb") as q:isgz=q.read(2)==b"\x1f\x8b"
op=gzip.open if isgz else open
sites=[]; samples=[]
with op(inp,"rt",errors="replace") as f:
 for line in f:
  if line.startswith("#CHROM"):samples=line.rstrip().split("\t")[9:13]
  elif not line.startswith("#"):
   a=line.rstrip().split("\t")
   if len(a)<13 or len(a[3])!=1 or len(a[4])!=1:continue
   fi=a[8].split(":"); gi=fi.index("GT") if "GT" in fi else 0; gs=[]
   for x in a[9:13]:
    z=x.split(":"); aa=(z[gi] if gi<len(z) else ".").replace("|","/").split("/")
    if len(aa)==2 and "." not in aa:
     al=[a[3],a[4]]
     try:gs.append(tuple(sorted((al[int(aa[0])],al[int(aa[1])]))))
     except:gs.append(None)
    else:gs.append(None)
   if len(set(x for x in gs if x))<2:continue
   cv=lo.convert_coordinate("chr1",int(a[1])-1)
   if not cv or cv[0][0]!="chr1":continue
   p=int(cv[0][1])+1; ref=a[3]; alt=a[4]
   if cv[0][2]=="-":
    tr=str.maketrans("ACGT","TGCA");ref=ref.translate(tr);alt=alt.translate(tr);gs=[tuple(sorted(y.translate(tr) for y in x)) if x else None for x in gs]
   sites.append((p,ref,alt,gs))
N=180; sel=[sites[int((i+0.5)*len(sites)/N)] for i in range(N)]
meta={}
with urllib.request.urlopen(META) as r:
 rd=csv.DictReader((x.decode() for x in r),delimiter="\t")
 for row in rd:
  if row["s"] in ids:meta[row["s"]]=(row.get("hgdp_tgp_meta.Genetic.region",""),row.get("hgdp_tgp_meta.Study.region",""),row.get("hgdp_tgp_meta.Population",""),row.get("hgdp_tgp_meta.Project",""))
vf=pysam.VariantFile(BCF); mat=[[[0,0] for j in ids] for k in range(4)]; found=0
for p,ref,alt,igs in sel:
 rec=None
 for rr in vf.fetch("chr1",p-1,p):
  if rr.pos==p and ref in rr.alleles and alt in rr.alleles:rec=rr;break
 if rec is None:continue
 found+=1; als=rec.alleles
 for j,rid in enumerate(ids):
  gt=rec.samples[rid].get("GT")
  if not gt or len(gt)!=2 or None in gt:continue
  rg=tuple(sorted((als[gt[0]],als[gt[1]])))
  for k in range(4):
   if igs[k]:
    mat[k][j][1]+=1
    if igs[k]==rg:mat[k][j][0]+=1
with open(out,"w") as w:
 w.write(f"selected\t{N}\nallele_matched\t{found}\n")
 for rid in ids:w.write("metadata\t"+rid+"\t"+"\t".join(meta.get(rid,("NA",)*4))+"\n")
 for k,s in enumerate(samples):
  for j,rid in enumerate(ids):
   m,c=mat[k][j];w.write(f"concordance\t{s}\t{rid}\t{m}/{c}\t{(m/c if c else 0):.6f}\n")
  best=max(range(4),key=lambda j:mat[k][j][0]/mat[k][j][1] if mat[k][j][1] else -1)
  lab={"CSA":"SAS"}.get(meta[ids[best]][0],meta[ids[best]][0])
  w.write(f"accepted\t{s}\t{ids[best]}\t{lab}\n")
